BLOCKED = ("import os", "subprocess", "open(", "__import__")

def run_analysis(client, question, df):
    code = client.messages.create(model=MODEL, max_tokens=600, system=PANDAS_PROMPT,
        messages=[{"role": "user", "content": question}]).content[0].text
    if any(b in code for b in BLOCKED):
        raise ValueError("blocked")
    scope = {"df": df}
    exec(code, scope)
    return scope.get("result")

