def propose_refund(client, order, reason):
    out = client.messages.create(model=MODEL, max_tokens=200, system=REFUND_POLICY_PROMPT,
        messages=[{"role": "user", "content": reason[:2000]}])
    payload = {"order_id": order.id, "amount": min(order.total, 50), "note": out.content[0].text}
    digest = hashlib.sha256(json.dumps(payload, sort_keys=True).encode()).hexdigest()
    approvals.create(kind="refund", payload=payload, payload_hash=digest, approver_group="billing")
    return {"status": "pending_approval", "hash": digest}

